'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  ArrowRightIcon,
  FilterIcon,
  ZapIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Switch } from '@/registry/ndeko/ui/switch';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import {
  INITIAL_RULE,
  MATCH_MODES,
  RULE_NAME,
  TRIGGERS,
  WORKSPACE_LINE,
  type Action,
  type ActionKind,
  type Condition,
  type FieldId,
  type MatchMode,
  type Rule,
  type TriggerId,
} from './data';
import { useHeightPresence } from './motion-parts';
import {
  ActionRow,
  AddSlot,
  ChoiceSelect,
  ConditionRow,
  RowError,
  Step,
} from './rule-parts';
import {
  ACTIONS_ERROR_KEY,
  actionForKind,
  conditionForField,
  errorsOf,
  hasErrors,
  replacedById,
  sameRule,
  sentenceOf,
  unusedActionKindOf,
  unusedFieldOf,
  withoutId,
  type RuleErrors,
} from './rule-model';
import { SaveButton, type SaveStatus } from './save-button';

const CARD_SURFACE =
  'bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

const SAVING_MS = 800;

const SAVED_HOLD_MS = 1200;

const FIRST_FREE_ID = 3;

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const NO_ERRORS: RuleErrors = {};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function shownErrorsOf(errors: RuleErrors, showsErrors: boolean) {
  if (showsErrors) {
    return errors;
  }
  return NO_ERRORS;
}

function delayOf(status: SaveStatus) {
  if (status === 'saving') {
    return SAVING_MS;
  }
  return SAVED_HOLD_MS;
}

function statusAfter(status: SaveStatus): SaveStatus {
  if (status === 'saving') {
    return 'saved';
  }
  return 'idle';
}

function conditionsHintOf(count: number, match: MatchMode) {
  if (count === 0) {
    return 'No condition: the rule runs every time';
  }
  if (count === 1) {
    return 'The rule runs only when this is true';
  }
  if (match === 'any') {
    return 'The rule runs when any of these is true';
  }
  return 'The rule runs when all of these are true';
}

function activeLabelOf(isActive: boolean) {
  if (isActive) {
    return 'Active';
  }
  return 'Paused';
}

function footerNoteOf(isDirty: boolean, status: SaveStatus) {
  if (status === 'saved') {
    return 'Rule saved';
  }
  if (isDirty) {
    return 'Unsaved changes';
  }
  return 'No changes';
}

function focusFirstControlOf(rowId: string) {
  const row = document.querySelector(`[data-rule-row="${rowId}"]`);
  const control = row?.querySelector<HTMLElement>('button, input');
  control?.focus();
}

function isMatchMode(value: unknown): value is MatchMode {
  return MATCH_MODES.some((mode) => mode.value === value);
}

type MatchSwitchProps = {
  value: MatchMode;
  onValueChange: (value: MatchMode) => void;
};

function MatchSwitch({ value, onValueChange }: MatchSwitchProps) {
  function changeValue(nextValue: unknown) {
    if (isMatchMode(nextValue)) {
      onValueChange(nextValue);
    }
  }

  return (
    <Tabs value={value} onValueChange={changeValue}>
      <TabsList variant='segmented' aria-label='Conditions to match'>
        {MATCH_MODES.map((mode) => (
          <TabsTab key={mode.value} value={mode.value}>
            {mode.label}
          </TabsTab>
        ))}
      </TabsList>
    </Tabs>
  );
}

function ActiveLabel({ isActive }: { isActive: boolean }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const label = activeLabelOf(isActive);

  return (
    <span className='relative inline-flex w-12'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={label}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {label}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export default function Automations01() {
  const [rule, setRule] = useState<Rule>(INITIAL_RULE);
  const [savedRule, setSavedRule] = useState<Rule>(INITIAL_RULE);
  const [status, setStatus] = useState<SaveStatus>('idle');
  const [showsErrors, setShowsErrors] = useState(false);
  const [isActive, setIsActive] = useState(true);
  const nextIdRef = useRef(FIRST_FREE_ID);
  const addConditionRef = useRef<HTMLButtonElement>(null);
  const addActionRef = useRef<HTMLButtonElement>(null);
  const heightPresence = useHeightPresence();
  const shouldReduceMotion = usePrefersReducedMotion();
  const switchVariants = swapVariantsOf(shouldReduceMotion);
  const errors = errorsOf(rule);
  const shownErrors = shownErrorsOf(errors, showsErrors);
  const isDirty = !sameRule(rule, savedRule);
  const conditionCount = rule.conditions.length;
  const hasSeveralConditions = conditionCount > 1;
  const sentence = sentenceOf(rule);
  const footerNote = footerNoteOf(isDirty, status);

  useEffect(() => {
    if (status === 'idle') {
      return;
    }
    function advance() {
      const next = statusAfter(status);
      setStatus(next);
    }
    const delay = delayOf(status);
    const timer = window.setTimeout(advance, delay);
    return () => window.clearTimeout(timer);
  }, [status]);

  function nextIdOf(prefix: string) {
    const id = `${prefix}-${nextIdRef.current}`;
    nextIdRef.current += 1;
    return id;
  }

  function patchRule(patch: Partial<Rule>) {
    setRule((current) => ({ ...current, ...patch }));
  }

  function changeTrigger(trigger: TriggerId) {
    patchRule({ trigger });
  }

  function changeMatch(match: MatchMode) {
    patchRule({ match });
  }

  function addCondition() {
    const id = nextIdOf('condition');
    const field = unusedFieldOf(rule.conditions);
    const condition = conditionForField(id, field);
    const conditions = [...rule.conditions, condition];
    patchRule({ conditions });
    window.requestAnimationFrame(() => focusFirstControlOf(id));
  }

  function changeCondition(condition: Condition) {
    const conditions = replacedById(rule.conditions, condition);
    patchRule({ conditions });
  }

  function changeConditionField(id: string, field: FieldId) {
    const condition = conditionForField(id, field);
    changeCondition(condition);
  }

  function removeCondition(id: string) {
    const conditions = withoutId(rule.conditions, id);
    patchRule({ conditions });
    addConditionRef.current?.focus();
  }

  function addAction() {
    const id = nextIdOf('action');
    const kind = unusedActionKindOf(rule.actions);
    const action = actionForKind(id, kind);
    const actions = [...rule.actions, action];
    patchRule({ actions });
    window.requestAnimationFrame(() => focusFirstControlOf(id));
  }

  function changeAction(action: Action) {
    const actions = replacedById(rule.actions, action);
    patchRule({ actions });
  }

  function changeActionKind(id: string, kind: ActionKind) {
    const action = actionForKind(id, kind);
    changeAction(action);
  }

  function removeAction(id: string) {
    const actions = withoutId(rule.actions, id);
    patchRule({ actions });
    addActionRef.current?.focus();
  }

  function discard() {
    setRule(savedRule);
    setShowsErrors(false);
  }

  function save() {
    if (hasErrors(errors)) {
      setShowsErrors(true);
      return;
    }
    setShowsErrors(false);
    setSavedRule(rule);
    setStatus('saving');
  }

  return (
    <div className='bg-background text-foreground min-h-dvh w-full'>
      <div className='mx-auto flex w-full max-w-3xl flex-col gap-5 px-4 py-6 md:px-6 md:py-10'>
        <header className='flex flex-col gap-1'>
          <p className='text-muted-foreground text-xs'>{WORKSPACE_LINE}</p>
          <div className='flex flex-wrap items-center justify-between gap-x-4 gap-y-2'>
            <h1 className='text-lg font-semibold text-balance'>{RULE_NAME}</h1>
            <label className='flex cursor-pointer items-center gap-2 text-[13px]'>
              <Switch checked={isActive} onCheckedChange={setIsActive} />
              <ActiveLabel isActive={isActive} />
            </label>
          </div>
        </header>
        <div className={`${CARD_SURFACE} p-4 pb-0 sm:p-6 sm:pb-0`}>
          <Step
            icon={ZapIcon}
            title='When'
            hint='The event that starts the rule'
          >
            <ChoiceSelect
              label='Event'
              value={rule.trigger}
              options={TRIGGERS}
              onValueChange={changeTrigger}
              className='sm:w-64'
            />
          </Step>
          <Step
            icon={FilterIcon}
            title='If'
            hint={conditionsHintOf(conditionCount, rule.match)}
            aside={
              <AnimatePresence initial={false}>
                {hasSeveralConditions && (
                  <motion.div
                    key='match'
                    variants={switchVariants}
                    initial='enter'
                    animate='visible'
                    exit='exit'
                    transition={SWAP_TRANSITION}
                  >
                    <MatchSwitch
                      value={rule.match}
                      onValueChange={changeMatch}
                    />
                  </motion.div>
                )}
              </AnimatePresence>
            }
          >
            <div className='flex flex-col'>
              <ul aria-label='Conditions' className='flex flex-col'>
                <AnimatePresence initial={false}>
                  {rule.conditions.map((condition) => (
                    <motion.li
                      key={condition.id}
                      data-rule-row={condition.id}
                      {...heightPresence}
                      className='overflow-hidden'
                    >
                      <div className='pb-2'>
                        <ConditionRow
                          condition={condition}
                          error={shownErrors[condition.id]}
                          onFieldChange={(field) =>
                            changeConditionField(condition.id, field)
                          }
                          onChange={changeCondition}
                          onRemove={() => removeCondition(condition.id)}
                        />
                      </div>
                    </motion.li>
                  ))}
                </AnimatePresence>
              </ul>
              <AddSlot
                ref={addConditionRef}
                label='Add condition'
                onAdd={addCondition}
              />
            </div>
          </Step>
          <Step
            icon={ArrowRightIcon}
            title='Then'
            hint='What happens, in this order'
            isLast
          >
            <div className='flex flex-col'>
              <ol aria-label='Actions' className='flex flex-col'>
                <AnimatePresence initial={false}>
                  {rule.actions.map((action) => (
                    <motion.li
                      key={action.id}
                      data-rule-row={action.id}
                      {...heightPresence}
                      className='overflow-hidden'
                    >
                      <div className='pb-2'>
                        <ActionRow
                          action={action}
                          onKindChange={(kind) =>
                            changeActionKind(action.id, kind)
                          }
                          onChange={changeAction}
                          onRemove={() => removeAction(action.id)}
                        />
                      </div>
                    </motion.li>
                  ))}
                </AnimatePresence>
              </ol>
              <AddSlot
                ref={addActionRef}
                label='Add action'
                onAdd={addAction}
              />
              <RowError
                id='automations-01-actions-error'
                error={shownErrors[ACTIONS_ERROR_KEY]}
              />
            </div>
          </Step>
        </div>
        <section
          aria-labelledby='automations-01-sentence'
          className='bg-foreground/[0.025] flex flex-col gap-1 rounded-xl px-4 py-3'
        >
          <h2
            id='automations-01-sentence'
            className='text-muted-foreground text-xs'
          >
            The rule reads
          </h2>
          <p className='text-[13px] leading-relaxed text-pretty'>{sentence}</p>
        </section>
        <div className='flex flex-wrap items-center justify-end gap-2'>
          <p role='status' className='text-muted-foreground me-auto text-xs'>
            {footerNote}
          </p>
          <Button variant='ghost' disabled={!isDirty} onClick={discard}>
            Discard
          </Button>
          <SaveButton
            status={status}
            idleLabel='Save rule'
            disabled={!isDirty}
            onSave={save}
          />
        </div>
      </div>
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId } from 'react';

import { PlusIcon, XIcon, type Icon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/registry/ndeko/ui/select';

import {
  ACTIONS,
  FIELDS,
  type Action,
  type ActionKind,
  type Condition,
  type FieldId,
  type Option,
  type OperatorId,
} from './data';
import { FADE_PRESENCE, useHeightPresence } from './motion-parts';
import {
  actionDefinitionOf,
  actionPhraseOf,
  conditionPhraseOf,
  digitsOf,
  fieldOf,
  targetOptionsOf,
} from './rule-model';

const FIELD_OPTIONS: Option<FieldId>[] = FIELDS.map((field) => ({
  value: field.id,
  label: field.label,
}));

const ACTION_OPTIONS: Option<ActionKind>[] = ACTIONS.map((action) => ({
  value: action.kind,
  label: action.label,
}));

const ADD_SLOT = [
  'flex h-9 w-full cursor-pointer items-center gap-2 rounded-lg px-2.5 text-[13px] text-muted-foreground outline-none',
  'hairline-border border-dashed border-foreground/20 transition-[color,border-color,scale] duration-150 ease-(--ease-out-strong)',
  'hover:border-foreground/35 hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/25 active:scale-[0.99]',
].join(' ');

function describedByOf(error: string | undefined, errorId: string) {
  if (error) {
    return errorId;
  }
  return undefined;
}

function targetLabelOf(target: string | null) {
  if (target === 'channel') {
    return 'Channel';
  }
  return 'Approver';
}

type ChoiceSelectProps<Value extends string> = {
  label: string;
  value: Value;
  options: Option<Value>[];
  className?: string;
  onValueChange: (value: Value) => void;
};

export function ChoiceSelect<Value extends string>({
  label,
  value,
  options,
  className,
  onValueChange,
}: ChoiceSelectProps<Value>) {
  function changeValue(nextValue: unknown) {
    const option = options.find((candidate) => candidate.value === nextValue);
    if (option) {
      onValueChange(option.value);
    }
  }

  return (
    <Select items={options} value={value} onValueChange={changeValue}>
      <SelectTrigger aria-label={label} className={className}>
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {options.map((option) => (
          <SelectItem key={option.value} value={option.value}>
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

type StepProps = {
  icon: Icon;
  title: string;
  hint: string;
  isLast?: boolean;
  aside?: React.ReactNode;
  children: React.ReactNode;
};

/** One step of the rule on a rail: the tile and the line on the left, the step's rows on the right. */
export function Step({
  icon: StepIcon,
  title,
  hint,
  isLast = false,
  aside,
  children,
}: StepProps) {
  const titleId = useId();
  const hasLine = !isLast;

  return (
    <section
      aria-labelledby={titleId}
      className='grid grid-cols-[2rem_minmax(0,1fr)] gap-x-3'
    >
      <div className='flex flex-col items-center'>
        <span className='keycap-3d text-muted-foreground flex size-8 shrink-0 items-center justify-center rounded-lg'>
          <StepIcon />
        </span>
        {hasLine && (
          <span
            aria-hidden='true'
            className='hairline-l border-border my-1.5 flex-1'
          />
        )}
      </div>
      <div className='flex min-w-0 flex-col gap-3 pb-6'>
        <div className='flex min-h-8 flex-wrap items-center justify-between gap-x-3 gap-y-1'>
          <div className='flex flex-col'>
            <h2 id={titleId} className='text-sm font-medium'>
              {title}
            </h2>
            <p className='text-muted-foreground text-xs'>{hint}</p>
          </div>
          {aside}
        </div>
        {children}
      </div>
    </section>
  );
}

type AddSlotProps = {
  label: string;
  ref?: React.Ref<HTMLButtonElement>;
  onAdd: () => void;
};

/** A dashed slot: the empty place where the next row goes. */
export function AddSlot({ label, ref, onAdd }: AddSlotProps) {
  return (
    <button ref={ref} type='button' onClick={onAdd} className={ADD_SLOT}>
      <PlusIcon className='size-4' />
      {label}
    </button>
  );
}

export function RowError({ id, error }: { id: string; error?: string }) {
  const heightPresence = useHeightPresence();

  return (
    <AnimatePresence initial={false}>
      {error && (
        <motion.p
          key='error'
          id={id}
          {...heightPresence}
          className='text-destructive-ink overflow-hidden text-xs'
        >
          <span className='block pt-1.5'>{error}</span>
        </motion.p>
      )}
    </AnimatePresence>
  );
}

type ValueControlProps = {
  condition: Condition;
  error?: string;
  errorId: string;
  onValueChange: (value: string) => void;
};

function ValueControl({
  condition,
  error,
  errorId,
  onValueChange,
}: ValueControlProps) {
  const field = fieldOf(condition.field);
  const isInvalid = Boolean(error);
  const describedBy = describedByOf(error, errorId);

  function typeAmount(event: React.ChangeEvent<HTMLInputElement>) {
    const digits = digitsOf(event.target.value);
    onValueChange(digits);
  }

  function typeText(event: React.ChangeEvent<HTMLInputElement>) {
    onValueChange(event.target.value);
  }

  if (field.kind === 'choice') {
    return (
      <ChoiceSelect
        label={`${field.label} value`}
        value={condition.value}
        options={field.choices}
        onValueChange={onValueChange}
        className='min-w-0 flex-1 sm:w-40 sm:flex-none'
      />
    );
  }

  if (field.kind === 'amount') {
    return (
      <div className='relative min-w-0 flex-1 sm:w-32 sm:flex-none'>
        <span
          aria-hidden='true'
          className='text-muted-foreground pointer-events-none absolute start-2.5 top-1/2 -translate-y-1/2 text-[13px]'
        >
          €
        </span>
        <Input
          inputMode='numeric'
          aria-label='Amount in euros'
          aria-invalid={isInvalid}
          aria-describedby={describedBy}
          value={condition.value}
          onChange={typeAmount}
          className='ps-6 tabular-nums'
        />
      </div>
    );
  }

  return (
    <Input
      aria-label='Part of the merchant name'
      aria-invalid={isInvalid}
      aria-describedby={describedBy}
      placeholder='For example: air'
      value={condition.value}
      onChange={typeText}
      className='min-w-0 flex-1 sm:w-40 sm:flex-none'
    />
  );
}

type ConditionRowProps = {
  condition: Condition;
  error?: string;
  onFieldChange: (fieldId: FieldId) => void;
  onChange: (condition: Condition) => void;
  onRemove: () => void;
};

export function ConditionRow({
  condition,
  error,
  onFieldChange,
  onChange,
  onRemove,
}: ConditionRowProps) {
  const errorId = useId();
  const field = fieldOf(condition.field);
  const phrase = conditionPhraseOf(condition);

  function changeOperator(operator: OperatorId) {
    onChange({ ...condition, operator });
  }

  function changeValue(value: string) {
    onChange({ ...condition, value });
  }

  return (
    <div className='flex flex-col'>
      <div className='flex flex-wrap items-center gap-2'>
        <ChoiceSelect
          label='Field'
          value={condition.field}
          options={FIELD_OPTIONS}
          onValueChange={onFieldChange}
          className='w-[calc(50%-0.25rem)] sm:w-32'
        />
        <ChoiceSelect
          label='Comparison'
          value={condition.operator}
          options={field.operators}
          onValueChange={changeOperator}
          className='w-[calc(50%-0.25rem)] sm:w-28'
        />
        <ValueControl
          condition={condition}
          error={error}
          errorId={errorId}
          onValueChange={changeValue}
        />
        <Button
          variant='ghost'
          size='icon'
          aria-label={`Remove the condition ${phrase}`}
          onClick={onRemove}
          className='ms-auto'
        >
          <XIcon />
        </Button>
      </div>
      <RowError id={errorId} error={error} />
    </div>
  );
}

type ActionRowProps = {
  action: Action;
  onKindChange: (kind: ActionKind) => void;
  onChange: (action: Action) => void;
  onRemove: () => void;
};

export function ActionRow({
  action,
  onKindChange,
  onChange,
  onRemove,
}: ActionRowProps) {
  const definition = actionDefinitionOf(action.kind);
  const targetOptions = targetOptionsOf(action.kind);
  const hasTarget = targetOptions.length > 0;
  const phrase = actionPhraseOf(action);
  const targetLabel = targetLabelOf(definition.target);

  function changeTarget(target: string) {
    onChange({ ...action, target });
  }

  return (
    <div className='flex flex-wrap items-center gap-2'>
      <ChoiceSelect
        label='Action'
        value={action.kind}
        options={ACTION_OPTIONS}
        onValueChange={onKindChange}
        className='min-w-0 flex-1 sm:w-48 sm:flex-none'
      />
      <AnimatePresence initial={false} mode='popLayout'>
        {hasTarget && (
          <motion.div
            key={action.kind}
            {...FADE_PRESENCE}
            className='order-last w-full sm:order-none sm:w-44'
          >
            <ChoiceSelect
              label={targetLabel}
              value={action.target}
              options={targetOptions}
              onValueChange={changeTarget}
              className='w-full'
            />
          </motion.div>
        )}
      </AnimatePresence>
      <Button
        variant='ghost'
        size='icon'
        aria-label={`Remove the action ${phrase}`}
        onClick={onRemove}
        className='ms-auto'
      >
        <XIcon />
      </Button>
    </div>
  );
}

import {
  ACTIONS,
  FIELDS,
  TARGETS,
  TRIGGERS,
  type Action,
  type ActionDefinition,
  type ActionKind,
  type Condition,
  type FieldDefinition,
  type FieldId,
  type Option,
  type Rule,
} from './data';

export type RuleErrors = Record<string, string>;

export const ACTIONS_ERROR_KEY = 'actions';

const CURRENCY = new Intl.NumberFormat('en-IE', {
  style: 'currency',
  currency: 'EUR',
  maximumFractionDigits: 0,
});

const MISSING_VALUE = '…';

export function fieldOf(id: FieldId): FieldDefinition {
  const field = FIELDS.find((candidate) => candidate.id === id);
  if (field) {
    return field;
  }
  return FIELDS[0];
}

export function actionDefinitionOf(kind: ActionKind): ActionDefinition {
  const action = ACTIONS.find((candidate) => candidate.kind === kind);
  if (action) {
    return action;
  }
  return ACTIONS[0];
}

function labelIn(options: Option<string>[], value: string) {
  const option = options.find((candidate) => candidate.value === value);
  if (option) {
    return option.label;
  }
  return MISSING_VALUE;
}

export function targetOptionsOf(kind: ActionKind) {
  const definition = actionDefinitionOf(kind);
  if (definition.target === null) {
    return [];
  }
  return TARGETS[definition.target];
}

export function firstTargetOf(kind: ActionKind) {
  const options = targetOptionsOf(kind);
  if (options.length === 0) {
    return '';
  }
  return options[0].value;
}

export function digitsOf(text: string) {
  return text.replace(/\D/g, '');
}

function amountLabelOf(value: string) {
  if (!value) {
    return MISSING_VALUE;
  }
  const amount = Number(value);
  return CURRENCY.format(amount);
}

function valueLabelOf(condition: Condition, field: FieldDefinition) {
  if (field.kind === 'amount') {
    return amountLabelOf(condition.value);
  }
  if (field.kind === 'choice') {
    return labelIn(field.choices, condition.value);
  }
  const trimmed = condition.value.trim();
  if (!trimmed) {
    return MISSING_VALUE;
  }
  return `“${trimmed}”`;
}

export function conditionPhraseOf(condition: Condition) {
  const field = fieldOf(condition.field);
  const operator = labelIn(field.operators, condition.operator);
  const value = valueLabelOf(condition, field);
  return `${field.noun} ${operator} ${value}`;
}

export function actionPhraseOf(action: Action) {
  const options = targetOptionsOf(action.kind);
  const target = labelIn(options, action.target);
  if (action.kind === 'ask-approval') {
    return `ask ${target} to approve`;
  }
  if (action.kind === 'post-channel') {
    return `post in ${target}`;
  }
  if (action.kind === 'flag-review') {
    return 'flag it for review';
  }
  if (action.kind === 'decline-payment') {
    return 'decline the payment';
  }
  return 'require a receipt';
}

function listOf(phrases: string[], joiner: string) {
  if (phrases.length <= 1) {
    return phrases.join('');
  }
  const leading = phrases.slice(0, -1);
  const head = leading.join(', ');
  const last = phrases[phrases.length - 1];
  return `${head} ${joiner} ${last}`;
}

function joinerOf(rule: Rule) {
  if (rule.match === 'any') {
    return 'or';
  }
  return 'and';
}

function triggerPhraseOf(rule: Rule) {
  const trigger = TRIGGERS.find((option) => option.value === rule.trigger);
  if (trigger) {
    return trigger.phrase;
  }
  return MISSING_VALUE;
}

function actionsPhraseOf(rule: Rule) {
  if (rule.actions.length === 0) {
    return 'nothing happens yet';
  }
  const phrases = rule.actions.map(actionPhraseOf);
  return listOf(phrases, 'and');
}

/** The rule read back as one sentence, so the person can check it says what they mean. */
export function sentenceOf(rule: Rule) {
  const trigger = triggerPhraseOf(rule);
  const actions = actionsPhraseOf(rule);
  if (rule.conditions.length === 0) {
    return `When ${trigger}, ${actions}.`;
  }
  const conditionPhrases = rule.conditions.map(conditionPhraseOf);
  const conditions = listOf(conditionPhrases, joinerOf(rule));
  return `When ${trigger}, if ${conditions}, ${actions}.`;
}

function conditionErrorOf(condition: Condition) {
  const field = fieldOf(condition.field);
  if (field.kind === 'amount') {
    const amount = Number(condition.value);
    if (amount > 0) {
      return null;
    }
    return 'Enter an amount above €0';
  }
  if (field.kind === 'text') {
    const hasText = condition.value.trim().length > 0;
    if (hasText) {
      return null;
    }
    return 'Enter part of the merchant name';
  }
  return null;
}

export function errorsOf(rule: Rule) {
  const errors: RuleErrors = {};
  for (const condition of rule.conditions) {
    const error = conditionErrorOf(condition);
    if (error) {
      errors[condition.id] = error;
    }
  }
  if (rule.actions.length === 0) {
    errors[ACTIONS_ERROR_KEY] =
      'Add at least one action, or the rule does nothing';
  }
  return errors;
}

export function hasErrors(errors: RuleErrors) {
  return Object.keys(errors).length > 0;
}

export function sameRule(first: Rule, second: Rule) {
  const firstText = JSON.stringify(first);
  const secondText = JSON.stringify(second);
  return firstText === secondText;
}

export function conditionForField(id: string, fieldId: FieldId): Condition {
  const field = fieldOf(fieldId);
  return {
    id,
    field: fieldId,
    operator: field.operators[0].value,
    value: field.defaultValue,
  };
}

export function actionForKind(id: string, kind: ActionKind): Action {
  return { id, kind, target: firstTargetOf(kind) };
}

/** The first field the conditions do not test yet, so a new row starts on something useful. */
export function unusedFieldOf(conditions: Condition[]) {
  const usedFields = conditions.map((condition) => condition.field);
  const unused = FIELDS.find((field) => !usedFields.includes(field.id));
  if (unused) {
    return unused.id;
  }
  return FIELDS[0].id;
}

/** The first kind the rule does not use yet, so a new action row starts on something useful. */
export function unusedActionKindOf(actions: Action[]) {
  const usedKinds = actions.map((action) => action.kind);
  const unused = ACTIONS.find(
    (definition) => !usedKinds.includes(definition.kind)
  );
  if (unused) {
    return unused.kind;
  }
  return ACTIONS[0].kind;
}

export function replacedById<Item extends { id: string }>(
  items: Item[],
  next: Item
) {
  return items.map((item) => {
    if (item.id === next.id) {
      return next;
    }
    return item;
  });
}

export function withoutId<Item extends { id: string }>(
  items: Item[],
  id: string
) {
  return items.filter((item) => item.id !== id);
}

