  label: string;
  target: TargetKind | null;
};

export type Condition = {
  id: string;
  field: FieldId;
  operator: OperatorId;
  value: string;
};

export type Action = {
  id: string;
  kind: ActionKind;
  target: string;
};

export type Rule = {
  trigger: TriggerId;
  match: MatchMode;
  conditions: Condition[];
  actions: Action[];
};

